CREATE OR REPLACE FUNCTION public.match_course_chunks(query_embedding extensions.vector,match_count integer DEFAULT 6,filter_course uuid DEFAULT NULL) RETURNS TABLE(id uuid,course_id uuid,topic_id uuid,content text,similarity double precision) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$ WITH visible_chunks AS MATERIALIZED (SELECT c.id,c.course_id,c.topic_id,c.content,c.embedding FROM public.course_chunks c WHERE c.embedding IS NOT NULL AND (filter_course IS NULL OR c.course_id=filter_course)) SELECT c.id,c.course_id,c.topic_id,c.content,1-(c.embedding <=> query_embedding) AS similarity FROM visible_chunks c ORDER BY c.embedding <=> query_embedding LIMIT least(greatest(match_count,1),20) $$;